# This formula is regenerated by the ankra-cli release workflow from
# packaging/homebrew/ankra.rb.tmpl in ankraio/ankra-cli. Manual edits here
# will be overwritten on the next release; change the template instead.
#
# There is deliberately no `version` stanza: `brew audit` fails a tap whose
# declared version it can already scan from the stable URL (redundant_version),
# and every release URL below carries the tag. That is why the URLs interpolate
# nothing - the release workflow substitutes the version into them directly.
class Ankra < Formula
  desc "Command-line interface for the Ankra Kubernetes platform"
  homepage "https://ankra.io"
  license "Apache-2.0"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.17.0/ankra-cli-darwin-arm64"
      sha256 "9c6ab63d7402b837e46ad0b379e7fa6ef73ef1a7fd2950717e6ac2064fc87447"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.17.0/ankra-cli-darwin-amd64"
      sha256 "58c5ae0daab91d94f9ac178e917a3a861db00bd30e8ac1b85fe07fb609059f3d"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.17.0/ankra-cli-linux-arm64"
      sha256 "6746f4c04c22791a8198d582b8035f7662e50b703a7ffb3c5892a526f193b508"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.17.0/ankra-cli-linux-amd64"
